svg.script:
(function(){'use strict';
const NS='http://www.w3.org/2000/svg',D2R=Math.PI/180,R2D=180/Math.PI,TAU=Math.PI*2;
const $=id=>document.getElementById(id),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),mod=(a,n)=>((a%n)+n)%n;
const E=(t,a,p)=>{const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);if(p)p.appendChild(e);return e};

/* ================= DATA (loaded from CSV) ================= */
const ST=new Map();let LRAW=[],stars=[],N=0,LN=[],CONS={},X,Y,Z,MG,CL,SX,SY,SQ,SE,SN,SU,SV,namedIdx=[],pmList=[],pmYear=NaN,status='';
const rows=t=>t.trim().split(/\r?\n/).map(l=>l.split(',').map(s=>s.trim())).filter(r=>r.length>2);

function loadMajor(t){let n=0;for(const r of rows(t)){const h=+r[0];if(!h)continue;const s=ST.get(h)||{h,pa:0,pd:0,plx:0,bv:NaN,sp:''};if(!s.det){s.ra=(+r[1]+r[2]/60+r[3]/3600)*15;s.dec=(r[4]==='0'?-1:1)*(+r[5]+r[6]/60+r[7]/3600);s.m=+r[8]}ST.set(h,s);n++}return n}

function loadDetail(t){let n=0;for(const r of rows(t)){const h=+r[0];if(!h)continue;const neg=r[4].startsWith('-');
 const s=ST.get(h)||{h};Object.assign(s,{ra:(+r[1]+r[2]/60+r[3]/3600)*15,dec:(neg?-1:1)*(Math.abs(+r[4])+r[5]/60+r[6]/3600),m:+r[7],plx:+r[8]||0,pa:+r[9]||0,pd:+r[10]||0,det:1,
 bv:parseFloat(r[r.length-1]),sp:r.slice(11,r.length-1).join(',')});ST.set(h,s);n++}return n}

function loadLines(t){LRAW=rows(t).map(r=>[r[0],+r[1],+r[2]]);return LRAW.length}

function cls(s){const b=s.bv;if(isFinite(b))return b<0?0:b<.3?1:b<.6?2:b<.8?3:b<1.15?4:5;const c=(s.sp||'')[0];return {O:0,B:0,A:1,F:2,G:3,K:4,M:5}[c]??6}

function finalize(){
 stars=[...ST.values()].filter(s=>isFinite(s.ra)&&isFinite(s.dec)&&isFinite(s.m));N=stars.length;
 X=new Float64Array(N);Y=new Float64Array(N);Z=new Float64Array(N);MG=new Float32Array(N);CL=new Uint8Array(N);
 SX=new Float32Array(N);SY=new Float32Array(N);SQ=new Float32Array(N);SE=new Float32Array(N);SN=new Float32Array(N);SU=new Float32Array(N);SV=new Uint8Array(N);
 const idx=new Map();pmList=[];
 stars.forEach((s,i)=>{s.i=i;idx.set(s.h,i);s.cons=[];s.name=NAMES[s.h]||'';MG[i]=s.m;CL[i]=cls(s);if(s.pa||s.pd)pmList.push(i);vec(i,s.ra,s.dec)});
 LN=[];CONS={};
 for(const [c,a,b] of LRAW){const ia=idx.get(a),ib=idx.get(b);if(ia===undefined||ib===undefined)continue;LN.push({a:ia,b:ib,z:ZOD.has(c)});(CONS[c]||(CONS[c]={set:new Set()})).set.add(ia).add(ib)}
 for(const c in CONS){let x=0,y=0,z=0;for(const i of CONS[c].set){const s=stars[i];s.cons.push(c);const ca=Math.cos(s.dec*D2R);x+=ca*Math.cos(s.ra*D2R);y+=ca*Math.sin(s.ra*D2R);z+=Math.sin(s.dec*D2R)}const l=Math.hypot(x,y,z)||1;CONS[c].v=[x/l,y/l,z/l]}
 namedIdx=stars.filter(s=>s.name).map(s=>s.i);pmYear=NaN;
 status=`${N.toLocaleString()} stars · ${pmList.length} with PM · ${LN.length} lines · ${Object.keys(CONS).length} constellations`}

function vec(i,ra,dec){const c=Math.cos(dec*D2R);X[i]=c*Math.cos(ra*D2R);Y[i]=c*Math.sin(ra*D2R);Z[i]=Math.sin(dec*D2R)}
function applyPM(yr){const dt=yr-1991.25;for(const i of pmList){const s=stars[i];vec(i,s.ra+s.pa/(3.6e6*Math.max(.02,Math.cos(s.dec*D2R)))*dt,clamp(s.dec+s.pd/3.6e6*dt,-89.999,89.999))}pmYear=yr}

/* ================= CONSTANTS ================= */
const CON={And:'Andromeda',Ant:'Antlia',Aps:'Apus',Aql:'Aquila',Aqr:'Aquarius',Ara:'Ara',Ari:'Aries',Aur:'Auriga',Boo:'Boötes',CMa:'Canis Major',CMi:'Canis Minor',CVn:'Canes Venatici',Cae:'Caelum',Cam:'Camelopardalis',Cap:'Capricornus',Car:'Carina',Cas:'Cassiopeia',Cen:'Centaurus',Cep:'Cepheus',Cet:'Cetus',Cha:'Chamaeleon',Cir:'Circinus',Cnc:'Cancer',Col:'Columba',Com:'Coma Berenices',CrA:'Corona Australis',CrB:'Corona Borealis',Crt:'Crater',Cru:'Crux',Crv:'Corvus',Cyg:'Cygnus',Del:'Delphinus',Dor:'Dorado',Dra:'Draco',Equ:'Equuleus',Eri:'Eridanus',For:'Fornax',Gem:'Gemini',Gru:'Grus',Her:'Hercules',Hor:'Horologium',Hya:'Hydra',Hyi:'Hydrus',Ind:'Indus',LMi:'Leo Minor',Lac:'Lacerta',Leo:'Leo',Lep:'Lepus',Lib:'Libra',Lup:'Lupus',Lyn:'Lynx',Lyr:'Lyra',Men:'Mensa',Mic:'Microscopium',Mon:'Monoceros',Mus:'Musca',Nor:'Norma',Oct:'Octans',Oph:'Ophiuchus',Ori:'Orion',Pav:'Pavo',Peg:'Pegasus',Per:'Perseus',Phe:'Phoenix',Pic:'Pictor',PsA:'Piscis Austrinus',Psc:'Pisces',Pup:'Puppis',Pyx:'Pyxis',Ret:'Reticulum',Scl:'Sculptor',Sco:'Scorpius',Sct:'Scutum',Ser:'Serpens',Sex:'Sextans',Sge:'Sagitta',Sgr:'Sagittarius',Tau:'Taurus',Tel:'Telescopium',TrA:'Triangulum Australe',Tri:'Triangulum',Tuc:'Tucana',UMa:'Ursa Major',UMi:'Ursa Minor',Vel:'Vela',Vir:'Virgo',Vol:'Volans',Vul:'Vulpecula'};
const ZOD=new Set(['Ari','Tau','Gem','Cnc','Leo','Vir','Lib','Sco','Sgr','Cap','Aqr','Psc']);
const NAMES={32349:'Sirius',30438:'Canopus',69673:'Arcturus',71683:'Rigil Kent',91262:'Vega',24608:'Capella',24436:'Rigel',37279:'Procyon',27989:'Betelgeuse',7588:'Achernar',68702:'Hadar',97649:'Altair',60718:'Acrux',21421:'Aldebaran',80763:'Antares',65474:'Spica',37826:'Pollux',113368:'Fomalhaut',102098:'Deneb',62434:'Mimosa',49669:'Regulus',33579:'Adhara',36850:'Castor',85927:'Shaula',61084:'Gacrux',25336:'Bellatrix',25428:'Elnath',45238:'Miaplacidus',26311:'Alnilam',26727:'Alnitak',25930:'Mintaka',27366:'Saiph',109268:'Alnair',62956:'Alioth',54061:'Dubhe',15863:'Mirfak',34444:'Wezen',86228:'Sargas',90185:'Kaus Australis',41037:'Avior',67301:'Alkaid',28360:'Menkalinan',82273:'Atria',31681:'Alhena',100751:'Peacock',11767:'Polaris',30324:'Mirzam',46390:'Alphard',9884:'Hamal',3419:'Diphda',92855:'Nunki',68933:'Menkent',65378:'Mizar',14576:'Algol',76267:'Alphecca',86032:'Rasalhague',107315:'Enif',113963:'Markab',677:'Alpheratz',5447:'Mirach',9640:'Almach',72607:'Kochab',53910:'Merak',58001:'Phecda',59774:'Megrez',95947:'Albireo',100453:'Sadr',3179:'Schedar',746:'Caph',57632:'Denebola',50583:'Algieba',68756:'Thuban',87833:'Eltanin'};
const SPCOL=['#9db4ff','#cad7ff','#f8f7ff','#fff1de','#ffd2a1','#ffa860','#e6ecff'];

/* ================= ASTRONOMY ================= */
const jdFrom=(y,m,d)=>{if(m<=2){y--;m+=12}const A=Math.floor(y/100),B=y>1582?2-A+Math.floor(A/4):0;return Math.floor(365.25*(y+4716))+Math.floor(30.6001*(m+1))+d+B-1524.5};
const leap=y=>(y%4==0&&y%100!=0)||y%400==0,ylen=y=>leap(y)?366:365;
const MN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const mdays=y=>[31,leap(y)?29:28,31,30,31,30,31,31,30,31,30,31];
function md(y,doy){const L=mdays(y);let m=0;while(m<11&&doy>L[m]){doy-=L[m];m++}return[m,doy]}
const doyOf=(y,m,d)=>mdays(y).slice(0,m).reduce((a,b)=>a+b,0)+d;
const EL={Mercury:[.38709927,.00000037,.20563593,.00001906,7.00497902,-.00594749,252.2503235,149472.67411175,77.45779628,.16047689,48.33076593,-.12534081],
Venus:[.72333566,.0000039,.00677672,-.00004107,3.39467605,-.0007889,181.9790995,58517.81538729,131.60246718,.00268329,76.67984255,-.27769418],
Earth:[1.00000261,.00000562,.01671123,-.00004392,-.00001531,-.01294668,100.46457166,35999.37244981,102.93768193,.32327364,0,0],
Mars:[1.52371034,.00001847,.0933941,.00007882,1.84969142,-.00813131,-4.55343205,19140.30268499,-23.94362959,.44441088,49.55953891,-.29257343],
Jupiter:[5.202887,-.00011607,.04838624,-.00013253,1.30439695,-.00183714,34.39644051,3034.74612775,14.72847983,.21252668,100.47390909,.20469106],
Saturn:[9.53667594,-.0012506,.05386179,-.00050991,2.48599187,.00193609,49.95424423,1222.49362201,92.59887831,-.41897216,113.66242448,-.28867794],
Uranus:[19.18916464,-.00196176,.04725744,-.00004397,.77263783,-.00242939,313.23810451,428.48202785,170.9542763,.40805281,74.01692503,.04240589],
Neptune:[30.06992276,.00026291,.00859048,.00005105,1.77004347,.00035372,-55.12002969,218.45945325,44.96476227,-.32241464,131.78422574,-.00508664]};
function kep(el,T){const a=el[0]+el[1]*T,e=el[2]+el[3]*T,I=(el[4]+el[5]*T)*D2R,L=el[6]+el[7]*T,wp=el[8]+el[9]*T,Om=el[10]+el[11]*T;
 const M=mod(L-wp,360)*D2R;let Ea=M+e*Math.sin(M);for(let i=0;i<8;i++)Ea+=(M-Ea+e*Math.sin(Ea))/(1-e*Math.cos(Ea));
 const xp=a*(Math.cos(Ea)-e),yp=a*Math.sqrt(1-e*e)*Math.sin(Ea),w=(wp-Om)*D2R,O=Om*D2R,cw=Math.cos(w),sw=Math.sin(w),cO=Math.cos(O),sO=Math.sin(O),cI=Math.cos(I),sI=Math.sin(I);
 return[(cw*cO-sw*sO*cI)*xp+(-sw*cO-cw*sO*cI)*yp,(cw*sO+sw*cO*cI)*xp+(-sw*sO+cw*cO*cI)*yp,sw*sI*xp+cw*sI*yp]}
const EPS=23.43928*D2R,ce=Math.cos(EPS),se=Math.sin(EPS);
const eq=v=>[v[0],v[1]*ce-v[2]*se,v[1]*se+v[2]*ce],unit=v=>{const l=Math.hypot(...v);return[v[0]/l,v[1]/l,v[2]/l]};
const PL=[['Mercury','#b9b2a8',0],['Venus','#fff1c8',-4],['Mars','#ff8a5c',.6],['Jupiter','#f3d9b0',-2.2],['Saturn','#e8cf8f',.6],['Uranus','#9fe3e8',5.7],['Neptune','#7aa0ff',7.8]];
let ephJD=NaN,eph=null;
function getEph(jd,T){if(jd===ephJD)return eph;ephJD=jd;const ea=kep(EL.Earth,T),list=[];
 const sv=[-ea[0],-ea[1],-ea[2]],sunLon=mod(Math.atan2(sv[1],sv[0])*R2D,360);
 list.push({n:'Sun',v:unit(eq(sv)),d:Math.hypot(...sv),mag:-26.7,c:'#ffd860'});
 const lon=218.32+481267.881*T+6.29*Math.sin((135+477198.87*T)*D2R)-1.27*Math.sin((259.3-413335.36*T)*D2R)+.66*Math.sin((235.7+890534.22*T)*D2R)+.21*Math.sin((269.9+954397.74*T)*D2R)-.19*Math.sin((357.5+35999.05*T)*D2R)-.11*Math.sin((186.5+966404.03*T)*D2R);
 const lat=5.13*Math.sin((93.3+483202.02*T)*D2R)+.28*Math.sin((228.2+960400.89*T)*D2R)-.28*Math.sin((318.3+6003.15*T)*D2R)-.17*Math.sin((217.6-407332.21*T)*D2R);
 const ml=(lon-1.3969713*T)*D2R,mb=lat*D2R,D=mod(lon-1.3969713*T-sunLon,360);
 list.push({n:'Moon',v:unit(eq([Math.cos(mb)*Math.cos(ml),Math.cos(mb)*Math.sin(ml),Math.sin(mb)])),mag:-12,c:'#e8ecf4',D,illum:(1-Math.cos(D*D2R))/2});
 for(const [n,c,mag] of PL){const p=kep(EL[n],T),g=[p[0]-ea[0],p[1]-ea[1],p[2]-ea[2]];list.push({n,v:unit(eq(g)),d:Math.hypot(...g),mag,c})}
 eph={list,sunLon};return eph}
function precMat(T){const s=Math.PI/648000,z=(2306.2181*T+1.09468*T*T+.018203*T*T*T)*s,Z_=(2306.2181*T+.30188*T*T+.017998*T*T*T)*s,th=(2004.3109*T-.42665*T*T-.041833*T*T*T)*s;
 const cz=Math.cos(Z_),sz=Math.sin(Z_),cZ=Math.cos(z),sZ=Math.sin(z),ct=Math.cos(th),st=Math.sin(th);
 return[[cz*ct*cZ-sz*sZ,-sz*ct*cZ-cz*sZ,-st*cZ],[cz*ct*sZ+sz*cZ,-sz*ct*sZ+cz*cZ,-st*sZ],[cz*st,-sz*st,ct]]}
const mul=(a,b)=>a.map(r=>[0,1,2].map(j=>r[0]*b[0][j]+r[1]*b[1][j]+r[2]*b[2][j])),tr=(m,v)=>[m[0][0]*v[0]+m[0][1]*v[1]+m[0][2]*v[2],m[1][0]*v[0]+m[1][1]*v[1]+m[1][2]*v[2],m[2][0]*v[0]+m[2][1]*v[1]+m[2][2]*v[2]];
function horizM(T,jd,lat,lon){const gm=280.46061837+360.98564736629*(jd-2451545)+.000387933*T*T,L=mod(gm+lon,360)*D2R,ph=lat*D2R,sp=Math.sin(ph),cp=Math.cos(ph),sL=Math.sin(L),cL=Math.cos(L);
 return{H:[[-sL,cL,0],[-sp*cL,-sp*sL,cp],[cp*cL,cp*sL,sp]],LST:L}}

/* ================= STATE ================= */
const S={lat:51.5,lon:0,year:2026,doy:314,hour:22,speed:0,mode:'sky',az:170,alt:35,fov:100,oy:3.5,op:.45,zoom:1,maglim:6.2,sel:-1,note:'Loading CSVs…',
 o:{lines:1,cn:1,sn:1,grid:1,ecl:1,bod:1,zod:1,twi:1}};
const JD=()=>{const[m,d]=md(S.year,S.doy);return jdFrom(S.year,m+1,d)+(S.hour-S.lon/15)/24};
function advance(h){S.hour+=h;while(S.hour>=24){S.hour-=24;S.doy++;if(S.doy>ylen(S.year)){S.doy=1;S.year++}}while(S.hour<0){S.hour+=24;S.doy--;if(S.doy<1){S.year--;S.doy=ylen(S.year)}}}
function setNow(){const d=new Date();S.year=d.getUTCFullYear();S.doy=doyOf(S.year,d.getUTCMonth(),d.getUTCDate());S.hour=d.getUTCHours()+d.getUTCMinutes()/60;advance(S.lon/15)}

/* ================= SCENE GRAPH ================= */
const svg=$('root');let W=1280,H=800;
const bg=E('rect',{id:'bg'},svg),hit=E('rect',{fill:'transparent'},svg);
const gG=E('g',{fill:'none'},svg),pHPl=E('path',{fill:'rgba(80,120,200,.10)',stroke:'none'},gG),pGrid=E('path',{stroke:'#3a5a96','stroke-width':.6,opacity:.55},gG),pMer=E('path',{stroke:'#7a6fd0','stroke-width':.8,'stroke-dasharray':'4 4',opacity:.7},gG),pEq=E('path',{stroke:'#46c2c8','stroke-width':1,'stroke-dasharray':'2 5',opacity:.85},gG),pEcl=E('path',{stroke:'#ffd860','stroke-width':1.1,opacity:.8},gG),pHor=E('path',{stroke:'#6fb1ff','stroke-width':1.6},gG);
const pBackS=E('path',{stroke:'#8aa0c8','stroke-width':1,'stroke-linecap':'round',opacity:.35},svg),pBackL=E('path',{stroke:'#4c78c9','stroke-width':.6,opacity:.25,fill:'none'},svg);
const gS=E('g',{'stroke-linecap':'round',fill:'none'},svg),bk=[];for(let i=0;i<70;i++)bk.push(E('path',{stroke:SPCOL[i%7]},gS));
const gL=E('g',{fill:'none'},svg),pL=E('path',{stroke:'#5b8be0','stroke-width':1.1},gL),pZ=E('path',{stroke:'#e8b64a','stroke-width':1.3},gL);
const gLab=E('g',{},svg),gBod=E('g',{},svg),ring=E('circle',{r:10,fill:'none',stroke:'#ffd860','stroke-width':1.5,display:'none'},svg);
const bodies=[];
for(const n of ['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune']){const g=E('g',{},gBod),o={n,g};
 if(n==='Sun'){E('circle',{r:16,fill:'#ffd860',opacity:.22},g);o.c=E('circle',{r:7,fill:'#ffe9a0'},g)}
 else if(n==='Moon'){o.c=E('circle',{r:8,fill:'#1b2438',stroke:'#59658a'},g);o.lit=E('path',{fill:'#f1f1e6'},g)}
 else o.c=E('circle',{r:3,fill:PL.find(p=>p[0]===n)[1]},g);
 o.t=E('text',{x:11,y:4,class:'bn'},g);o.t.textContent=n;bodies.push(o)}
const pool=[];let pn=0;
function lab(x,y,t,c,a){let e=pool[pn];if(!e)e=pool[pn]=E('text',{},gLab);pn++;e.setAttribute('x',x.toFixed(1));e.setAttribute('y',y.toFixed(1));e.setAttribute('class',c);e.setAttribute('text-anchor',a||'start');e.textContent=t;e.style.display=''}
const hud=E('text',{class:'mono hud'},svg),noteT=E('text',{class:'note','text-anchor':'middle'},svg),tip=E('text',{class:'tip',display:'none'},svg);

/* ================= LOADING UI ================= */
const loadG=E('g',{},svg);
const loadTxt=E('text',{class:'loading'},loadG);loadTxt.textContent='Loading CSVs…';
const loadBg=E('rect',{fill:'#03060f',opacity:.9},svg);
loadBg.style.display='none';loadG.style.display='';

/* ================= AUTO-LOAD ================= */
const CSV_URLS=[
 'https://svgfpsaiagents.github.io/svgfpsgameAI/hip_lite_major.csv',
 'https://svgfpsaiagents.github.io/svgfpsgameAI/hip_constellation_line_star.csv',
 'https://svgfpsaiagents.github.io/svgfpsgameAI/hip_constellation_line.csv'
];

async function autoLoad(){
 loadBg.style.display='';loadBg.setAttribute('width',W);loadBg.setAttribute('height',H);loadG.style.display='';
 let loaded=0,errors=[];
 for(const url of CSV_URLS){
  try{
   const r=await fetch(url);
   if(!r.ok)throw new Error(`HTTP ${r.status}`);
   const t=await r.text();
   const firstRow=rows(t)[0]||[];
   if(firstRow.length===3&&isNaN(+firstRow[0])){loadLines(t);loaded++}
   else if(firstRow.length>=12){loadDetail(t);loaded++}
   else if(firstRow.length===9&&!isNaN(+firstRow[0])){loadMajor(t);loaded++}
   else{errors.push(`${url.split('/').pop()}: unrecognised format`)}
  }catch(e){errors.push(`${url.split('/').pop()}: ${e.message}`)}
 }
 if(loaded>0){
  finalize();
  S.note=errors.length?`Auto-loaded ${loaded}/3 files · ${errors.join(' · ')}`:`Auto-loaded ${loaded}/3 CSVs · ${status}`;
 }else{
  S.note='Auto-load failed · '+errors.join(' · ')+' · Please use the Load CSV button or drop files.';
 }
 loadBg.style.display='none';loadG.style.display='none';
 sync();req();
}

/* ================= UI PANELS ================= */
const syncs=[];const sync=()=>syncs.forEach(f=>f());let want=0;const req=()=>{if(!want){want=1;requestAnimationFrame(draw)}};
function panel(w){const g=E('g',{},svg);E('rect',{width:w,height:10,rx:6,fill:'#070d1a','fill-opacity':.86,stroke:'#22406e'},g);return g}
function btn(p,x,y,w,h,t,fn,isOn){const g=E('g',{class:'btn',transform:`translate(${x} ${y})`},p);E('rect',{width:w,height:h,rx:3},g);const tx=E('text',{x:w/2,y:h/2+3.6,'text-anchor':'middle'},g);tx.textContent=t;g.addEventListener('click',e=>{e.stopPropagation();fn();sync();req()});if(isOn)syncs.push(()=>g.classList.toggle('on',!!isOn()));return g}
function slider(p,x,y,w,label,min,max,step,get,set,fmt){E('text',{x,y:y+8,class:'h'},p).textContent=label;const vt=E('text',{x:x+w,y:y+8,'text-anchor':'end'},p);
 E('rect',{x,y:y+15,width:w,height:3,rx:1.5,fill:'#27406e'},p);const k=E('circle',{r:5.5,cy:y+16.5,fill:'#6fb1ff'},p),h=E('rect',{x:x-6,y:y+8,width:w+12,height:18,fill:'transparent',style:'cursor:pointer'},p);let dn=0;
 const upd=()=>{const v=get();k.setAttribute('cx',x+(v-min)/(max-min)*w);vt.textContent=fmt?fmt(v):v};syncs.push(upd);
 const mv=e=>{const r=h.getBoundingClientRect(),l=r.left+r.width*6/(w+12),f=clamp((e.clientX-l)/(r.width*w/(w+12)),0,1);set(Math.round((min+f*(max-min))/step)*step);sync();req()};
 h.addEventListener('pointerdown',e=>{dn=1;h.setPointerCapture(e.pointerId);mv(e)});h.addEventListener('pointermove',e=>{if(dn)mv(e)});h.addEventListener('pointerup',()=>dn=0)}
function tog(p,x,y,t,k){const g=E('g',{class:'btn tg',transform:`translate(${x} ${y})`},p),b=E('rect',{width:11,height:11,rx:2},g);E('text',{x:16,y:9.5},g).textContent=t;E('rect',{width:112,height:14,y:-1,fill:'transparent'},g);
