/* ================= INTERACTION ================= */
let drag=null;
function pickAt(mx,my){let b=-1,bs=1e9;for(let i=0;i<N;i++){if(!SV[i]||MG[i]>S.maglim+.5)continue;if(S.mode!=='out'&&SU[i]<0)continue;if(S.mode==='out'&&SQ[i]<0)continue;const dx=SX[i]-mx,dy=SY[i]-my,d=dx*dx+dy*dy;if(d>196)continue;const sc=d+MG[i]*14;if(sc<bs){bs=sc;b=i}}return b}
const svgPt=e=>{const r=svg.getBoundingClientRect();return[(e.clientX-r.left)*W/r.width,(e.clientY-r.top)*H/r.height]};
hit.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,mv:0};hit.setPointerCapture(e.pointerId);tip.style.display='none'});
hit.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;drag.mv+=Math.abs(dx)+Math.abs(dy);
  if(S.mode==='out'){S.oy-=dx*.008;S.op=clamp(S.op+dy*.008,-1.55,1.55)}else{const k=S.fov/H*(S.mode==='sky'?1.1:1);S.az=mod(S.az-dx*k,360);S.alt=clamp(S.alt+dy*k,-35,90)}req();return}
 const[mx,my]=svgPt(e),i=pickAt(mx,my);if(i>=0){const s=stars[i];tip.textContent=(s.name||'HIP '+s.h)+'  m'+s.m.toFixed(1);tip.setAttribute('x',mx+12);tip.setAttribute('y',my-10);tip.style.display=''}else tip.style.display='none'});
hit.addEventListener('pointerup',e=>{if(drag&&drag.mv<4){const[mx,my]=svgPt(e);S.sel=pickAt(mx,my)}drag=null;req()});
svg.addEventListener('wheel',e=>{e.preventDefault();const f=Math.exp(e.deltaY*.0012);if(S.mode==='out')S.zoom=clamp(S.zoom/f,.5,4);else S.fov=clamp(S.fov*f,8,S.mode==='persp'?120:170);req()},{passive:false});
addEventListener('keydown',e=>{const k=e.key,st=S.fov/20;let h=1;if(k==='ArrowLeft')S.az=mod(S.az-st,360);else if(k==='ArrowRight')S.az=mod(S.az+st,360);else if(k==='ArrowUp')S.alt=clamp(S.alt+st,-35,90);else if(k==='ArrowDown')S.alt=clamp(S.alt-st,-35,90);
 else if(k==='+'||k==='=')S.fov=clamp(S.fov/1.15,8,170);else if(k==='-')S.fov=clamp(S.fov*1.15,8,170);else if(k===' '){S.speed=S.speed?0:1;e.preventDefault()}
 else if(k==='l')S.o.lines^=1;else if(k==='n')S.o.sn^=1;else if(k==='g')S.o.grid^=1;else if(k==='m')S.mode=['sky','persp','out'][(['sky','persp','out'].indexOf(S.mode)+1)%3];else h=0;if(h){sync();req()}});

function readFiles(fs){const ps=[...fs].map(f=>f.text().then(t=>[f.name,t]));Promise.all(ps).then(a=>{
 const msg=[];let hasMajor=false,hasDetail=false,hasLines=false;
 for(const[nm,t]of a){const r=rows(t)[0]||[];
  if(r.length===3&&isNaN(+r[0])){msg.push(nm+': '+loadLines(t)+' lines');hasLines=true}
  else if(r.length>=12){msg.push(nm+': '+loadDetail(t)+' detail');hasDetail=true}
  else if(r.length===9&&!isNaN(+r[0])){loadMajor(t);msg.push(nm+': major');hasMajor=true}
  else msg.push(nm+': unrecognised (need 3, 9, or ≥12 columns)')}
 finalize();S.note='Loaded: '+msg.join(' · ');S.sel=-1;
 if(N>0&&!hasMajor&&!hasDetail){S.note='Warning: no major/detail CSV found — only lines loaded';}
 req()}).catch(err=>{S.note='Error loading files: '+err.message;req()})}

addEventListener('resize',layout);
layout();sync();req();
autoLoad();

// expose loader for testing
if(typeof window!=='undefined')window.__loadCSV=(major,detail,lines)=>{if(major)loadMajor(major);if(detail)loadDetail(detail);if(lines)loadLines(lines);finalize();layout();sync();req()};
})();
